def get_max_triples(n):
    a = [(i * i) - i + 1 for i in range(1, n + 1)]
    count = 0

    mod_count = [0, 0, 0]
    for value in a:
        mod_count[value % 3] += 1

    # Choose 3 from the same modulo class
    for i in range(3):
        if mod_count[i] >= 3:
            count += (mod_count[i] * (mod_count[i] - 1) * (mod_count[i] - 2)) // 6

    # Choose 2 from mod class i and 1 from mod class j such that i != j
    for i in range(3):
        for j in range(i + 1, 3):
            count += mod_count[i] * (mod_count[i] - 1) // 2 * mod_count[j]
            count += mod_count[j] * (mod_count[j] - 1) // 2 * mod_count[i]

    return count
